"use client";
import { useEffect, useState, type ComponentProps, type CSSProperties } from "react";
import { cn } from "./lib/cn";
import { diffLines, type DiffOp } from "./lib/diff-lines";
import "./diff-text.css";

/** Word-level changes from one text to another; spaces are their own tokens, so a change never eats its neighbours. */
export function diffWords(before: string, after: string): DiffOp[] {
  const words = (text: string) => text.split(/(\s+)/).filter(Boolean);
  return diffLines(words(before), words(after));
}

export type DiffTextProps = Omit<ComponentProps<"span">, "children"> & {
  /** The text to show. When it changes, the change plays out in place. */
  value: string;
  /** Leaves removed words struck through and added words marked, for review, instead of settling to plain text. */
  keep?: boolean;
  /** The text to compare with when `keep` is on and nothing has changed yet. */
  previous?: string;
};

/**
 * Shows a change to a piece of text where it stands: removed words are struck through and close up, added words grow
 * in with a brief tint, and then it settles to plain text. With `keep` the marks stay for review. For AI edits,
 * suggested rewrites and changelog lines. Under reduced motion the change is marked, then the text swaps.
 */
export function DiffText({ value, keep = false, previous, className, ...props }: DiffTextProps) {
  const [frame, setFrame] = useState(() => ({ value, ops: previous !== undefined ? diffWords(previous, value) : null, run: 0 }));
  if (frame.value !== value) setFrame({ value, ops: diffWords(frame.value, value), run: frame.run + 1 });
  const [settled, setSettled] = useState(-1);

  useEffect(() => {
    if (keep || frame.run === 0) return;
    const timer = window.setTimeout(() => setSettled(frame.run), 1500);
    return () => window.clearTimeout(timer);
  }, [frame.run, keep]);

  const ops = frame.ops && (keep || settled !== frame.run) ? frame.ops : null;
  let removed = 0,
    added = 0;
  return (
    <span data-slot="diff-text" data-keep={keep ? "" : undefined} className={cn(className)} {...props}>
      {ops
        ? ops.map((op, i) => {
            if (op.type === "eq") return op.text;
            const del = op.type === "del";
            const order = del ? removed++ : added++;
            const Tag = del ? "del" : "ins";
            const start = keep && (ops[i - 1]?.type !== op.type);
            return (
              <Tag key={`${frame.run}-${i}`} data-slot={del ? "dt-del" : "dt-ins"} style={{ "--dt-i": order } as CSSProperties}>
                {start && <span className="sr-only">{del ? "removed: " : "added: "}</span>}
                <span>{op.text}</span>
              </Tag>
            );
          })
        : frame.value}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type DiffOp = { type: "eq" | "del" | "add"; text: string; a?: number; b?: number };

/** Line diff: trims what both sides share, then finds the longest common run of lines in the middle. */
export function diffLines(before: readonly string[], after: readonly string[]): DiffOp[] {
  let start = 0;
  while (start < before.length && start < after.length && before[start] === after[start]) start++;
  let endA = before.length,
    endB = after.length;
  while (endA > start && endB > start && before[endA - 1] === after[endB - 1]) {
    endA--;
    endB--;
  }
  const a = before.slice(start, endA),
    b = after.slice(start, endB);
  const ops: DiffOp[] = [];
  for (let i = 0; i < start; i++) ops.push({ type: "eq", text: before[i], a: i + 1, b: i + 1 });
  const n = a.length,
    m = b.length;
  if (n * m > 4_000_000) {
    a.forEach((text, i) => ops.push({ type: "del", text, a: start + i + 1 }));
    b.forEach((text, j) => ops.push({ type: "add", text, b: start + j + 1 }));
  } else {
    const width = m + 1;
    const table = new Uint32Array((n + 1) * width);
    for (let i = n - 1; i >= 0; i--)
      for (let j = m - 1; j >= 0; j--)
        table[i * width + j] = a[i] === b[j] ? table[(i + 1) * width + j + 1] + 1 : Math.max(table[(i + 1) * width + j], table[i * width + j + 1]);
    let i = 0,
      j = 0;
    while (i < n || j < m) {
      if (i < n && j < m && a[i] === b[j]) {
        ops.push({ type: "eq", text: a[i], a: start + i + 1, b: start + j + 1 });
        i++;
        j++;
      } else if (i < n && (j === m || table[(i + 1) * width + j] >= table[i * width + j + 1])) {
        ops.push({ type: "del", text: a[i], a: start + i + 1 });
        i++;
      } else {
        ops.push({ type: "add", text: b[j], b: start + j + 1 });
        j++;
      }
    }
  }
  for (let k = endA; k < before.length; k++) ops.push({ type: "eq", text: before[k], a: k + 1, b: endB + (k - endA) + 1 });
  return ops;
}

/* diff-text.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Diff text: removed words strike, then close up; added words open up with a passing tint. */
  [data-slot="diff-text"] :is([data-slot="dt-del"], [data-slot="dt-ins"]) { display: inline-grid; grid-template-columns: 1fr; text-decoration: none; vertical-align: bottom; }
  [data-slot="diff-text"] :is([data-slot="dt-del"], [data-slot="dt-ins"]) > span:not(.sr-only) { min-width: 0; overflow: hidden; white-space: pre; }
  [data-slot="diff-text"] [data-slot="dt-del"] > span { color: var(--muted-foreground); text-decoration: line-through; text-decoration-color: var(--destructive); animation: dt-strike 0.3s var(--ease-out) calc(var(--dt-i) * 30ms) backwards; }
  [data-slot="diff-text"] [data-slot="dt-del"] { animation: dt-out 0.45s var(--ease-in-out) calc(440ms + var(--dt-i) * 30ms) forwards; }
  [data-slot="diff-text"] [data-slot="dt-ins"] { border-radius: 2px; animation: dt-in 0.5s var(--ease-out) calc(720ms + var(--dt-i) * 30ms) backwards, dt-tint 1.4s var(--ease-out) calc(720ms + var(--dt-i) * 30ms) backwards; }
  [data-slot="diff-text"][data-keep] [data-slot="dt-del"] { animation: none; }
  [data-slot="diff-text"][data-keep] [data-slot="dt-del"] + [data-slot="dt-ins"] { margin-left: 0.3em; }
  [data-slot="diff-text"][data-keep] [data-slot="dt-ins"] { background: color-mix(in oklab, var(--success) 18%, transparent); animation: dt-in 0.5s var(--ease-out) calc(300ms + var(--dt-i) * 30ms) backwards; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="diff-text"] :is([data-slot="dt-del"], [data-slot="dt-ins"]), [data-slot="diff-text"] [data-slot="dt-del"] > span { animation: none; }
  }
  @keyframes dt-strike { from { color: var(--foreground); text-decoration-color: transparent; } }
  @keyframes dt-out { to { grid-template-columns: 0fr; opacity: 0; } }
  @keyframes dt-in { from { grid-template-columns: 0fr; opacity: 0; } }
  @keyframes dt-tint { 0%, 45% { background-color: color-mix(in oklab, var(--success) 22%, transparent); } 100% { background-color: transparent; } }
}
